  function orderFilters(){return `<label>${esc(tr('الترتيب','Sort'))}<select name="sort">${[['active_oldest',tr('النشط الأقدم أولًا','Oldest active first')],['newest',tr('الأحدث أولًا','Newest first')],['oldest',tr('الأقدم أولًا','Oldest first')]].map(([v,l])=>`<option value="${v}" ${state.filters.sort===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label>${field(tr('بحث برقم الطلب','Order number'),'search',state.filters.search||'')}${field(tr('الحي','Neighborhood'),'neighborhood',state.filters.neighborhood||'')}<label>${esc(tr('الحالة','Status'))}<select name="status"><option value="">${esc(tr('كل الحالات','All statuses'))}</option>${['new','accepted','preparing','ready','completed','cancelled'].map(v=>`<option value="${v}" ${state.filters.status===v?'selected':''}>${esc(statusName(v))}</option>`).join('')}</select></label><label>${esc(tr('السائق','Driver'))}<select name="driver_id"><option value="">${esc(tr('كل السائقين المسموحين','All permitted drivers'))}</option>${selectOptions(state.drivers||[],state.filters.driver_id,x=>x.display_name)}</select></label>`;}
  function duration(t){if(!t||t.seconds==null)return esc(t?.state==='not_applicable'?tr('لا ينطبق','Not applicable'):t?.state==='cancelled'?tr('مستبعد','Excluded'):t?.state==='missing'?tr('بيانات الزمن ناقصة','Timing incomplete'):tr('لم يبدأ','Not started'));const seconds=Math.max(0,Math.floor(Number(t.seconds)));return `${num(Math.floor(seconds/60))}:${String(seconds%60).padStart(2,'0')}${t.state==='running'?` · ${esc(tr('جارٍ','Running'))}`:''}`;}
