  async function orders(){heading(tr('الطلبات','Orders'),tr('النشط الأقدم أولًا. انقر رقم الطلب لعرض تفاصيله وإجراءاته.','Oldest active first. Open an order number for details and actions.'),`<button class="quiet" data-action="refresh">${esc(tr('تحديث','Refresh'))}</button>`);await loadBranches();if(isManager()){const peopleData=await api('/api/operations/people');state.drivers=(peopleData.users||[]).filter(x=>x.role==='driver');}const d=await api(`/api/orders?${queryFilters()}`);state.orders=(d.orders||[]).map(normalizeOrder);$('#content').innerHTML=`<div class="stack">${filterForm()}${['owner','branch_manager'].includes(state.user.role)?`<div class="actions"><button class="quiet" data-action="branch-availability">${esc(tr('إدارة توفر الأصناف بالفرع','Branch item availability'))}</button></div>`:''}${orderList(state.orders)}${d.next_offset!=null?`<button class="quiet" data-action="more-orders" data-offset="${esc(d.next_offset)}">${esc(tr('تحميل المزيد','Load more'))}</button>`:''}</div>`;}
  async function orderDetail(id){const d=await api(`/api/orders/${encodeURIComponent(id)}`);const o=normalizeOrder(d.order);const existing=state.orders.findIndex(x=>x.id===id);if(existing>=0)state.orders[existing]=o;else state.orders.push(o);modal(tr('تفاصيل الطلب','Order details'),`<div class="stack">${orderCard(o)}${o.identity_kind==='guest'||o.customer_identity?.identity_kind==='guest'||o.customer?.identity_kind==='guest'?notice(tr('ضيف — الجوال غير موثق. التأكيد التشغيلي بالاتصال لا يوثّق الرقم.','Guest — phone unverified. An operational call does not verify the phone.'),'warn'):''}<dl class="data-grid">${dataItem(tr('العميل','Customer'),o.customer_name||'—')}${dataItem(tr('رقم الاتصال','Contact phone'),o.customer?.phone||'—')}${dataItem(tr('العنوان','Address'),o.address||'—')}${dataItem(tr('انتظار القبول','Acceptance wait'),duration(o.timings?.acceptance_wait))}${dataItem(tr('انتظار السائق','Driver wait'),duration(o.timings?.driver_wait))}${dataItem(tr('الزمن الكلي','Total duration'),duration(o.timings?.total))}</dl>${o.customer_location?`<div class="actions"><a class="button quiet" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(`${o.customer_location.lat},${o.customer_location.lng}`)}&travelmode=driving">${esc(tr('اتجاهات موقع العميل المحدد','Directions to selected customer location'))}</a>${isManager()?`<button class="quiet" data-action="nearest-branches" data-id="${esc(id)}">${esc(tr('أقرب الفروع المؤهلة','Nearest eligible branches'))}</button>`:''}</div>`:''}${state.user.role!=='driver'?`<button class="quiet" data-action="order-chat" data-id="${esc(id)}">${esc(tr('محادثة الطلب','Order conversation'))}</button>`:''}<details><summary>${esc(tr('سجل الأحداث','Event history'))}</summary>${table([tr('الوقت','Time'),tr('الحدث','Event')],(d.events||[]).map(x=>[esc(datetime(x.created_at)),esc(x.event_type||x.type||x.status||'—')]))}</details></div>`);}
