  function hoursEditor(name,value) { return `<fieldset class="full"><legend>${esc(name==='opening_hours'?tr('ساعات استقبال الطلبات — الرياض','Order hours — Riyadh'):tr('ساعات التوصيل — الرياض','Delivery hours — Riyadh'))}</legend><div id="${name}-rows" class="stack">${(value||[]).map((row,i)=>hoursRow(name,row,i)).join('')}</div><div class="actions"><button type="button" class="quiet small" data-action="add-hours" data-name="${name}">${esc(tr('إضافة فترة','Add hours interval'))}</button></div></fieldset>`; }
