  async function branchAvailability() { await loadBranches();const branchId=state.filters.branch_id||(state.user.branch_ids||[])[0]; if(!branchId)throw new Error(tr('اختر فرعًا مخولًا من الفلاتر أولًا.','Choose an authorized branch from the filters first.'));const d=await api(`/api/catalog?brand_id=${encodeURIComponent(state.user.brand_id)}&branch_id=${encodeURIComponent(branchId)}`);modal(tr('إيقاف / استئناف توفر صنف بالفرع','Pause / resume branch item availability'),`<form><label>${esc(tr('الفرع','Branch'))}<input readonly value="${esc(state.branches.find(b=>b.id===branchId)?.name||branchId)}"></label><label>${esc(tr('الصنف','Item'))}<select name="product_id" required>${selectOptions(d.products||[],'',p=>p.name)}</select></label>${check(tr('إتاحة الصنف في هذا الفرع — مع بقاء قيود المدينة','Enable item in this branch — city policies stay enforced'),'available',false)}${textarea(tr('سبب التغيير','Reason for change'),'reason','',true)}${formEnd(tr('حفظ التوفر','Save availability'))}</form>`,async(fd)=>{await mutation(`/api/branches/${encodeURIComponent(branchId)}/products/${encodeURIComponent(fd.get('product_id'))}/availability`,{available:fd.has('available'),reason:fd.get('reason')});closeModal();await loadPage();}); }
  async function managerHandover(id) { const d=await api('/api/shifts/current');const list=(d.available_manager_shifts||[]).filter(s=>s.id!==id&&s.user_id!==state.user.id);modal(tr('تسليم مسؤولية المناوبة','Hand over shift responsibility'),`<form><label>${esc(tr('شفت المدير المستلم','Receiving manager shift'))}<select name="target_manager_shift_id" required><option value="">${esc(tr('اختر المدير المستلم','Choose receiving manager'))}</option>${selectOptions(list,'',s=>`${s.display_name} · ${s.id}`)}</select></label>${textarea(tr('سبب التسليم والسياق التشغيلي','Handover reason and operational context'),'reason','',true)}${notice(tr('تتجمد المناوبة للإسناد الجديد ويقبل المدير المستلم المسؤولية من حسابه. النقد يُسلم ويُؤكد بإجراء مستقل.','New assignments are frozen; the receiving manager accepts responsibility from their account. Cash handover and confirmation remain separate.'))}${formEnd(tr('اقتراح تسليم المناوبة','Propose shift handover'))}</form>`,async(fd)=>{await mutation(`/api/shifts/${encodeURIComponent(id)}/handover-manager`,{target_manager_shift_id:fd.get('target_manager_shift_id'),reason:fd.get('reason')});closeModal();await loadPage();}); }
  async function refundOrder(id) { const d=await api(`/api/orders/${encodeURIComponent(id)}`),o=normalizeOrder(d.order);const shifts=await api('/api/shifts/current');const q={};for(const i of o.items)q[i.product_id]={name:i.name,quantity:(q[i.product_id]?.quantity||0)+i.quantity};modal(tr('استرداد مأذون مرتبط بالطلب','Authorized order refund'),`<form class="form-columns">${notice(tr('سجّل الاسترداد الفعلي للعميل. لا يعدّل تقفيلة تاريخية؛ الاسترداد النقدي يحتاج عهدة شفت مفتوح كافية.','Record the actual customer refund. Historical closures stay immutable; cash refunds require sufficient custody in an open shift.'),'warn')}${amountField(tr('مبلغ الاسترداد بالريال','Refund amount (SAR)'),'amount',0)}<label>${esc(tr('طريقة التحصيل الأصلية','Original collection method'))}<input readonly value="${esc(o.payment_method==='cash'?tr('كاش','Cash'):tr('شبكة','Card'))}"></label><label class="full">${esc(tr('شفت العهدة الذي يصرف الاسترداد','Custody shift funding the refund'))}<select name="shift_id"><option value="">${esc(tr('شفت التحصيل الأصلي، إن كان مفتوحًا','Original collection shift, if open'))}</option>${selectOptions((shifts.shifts||[]).filter(s=>['open','closing'].includes(s.status)),'',s=>`${s.display_name} · ${s.id}`)}</select></label><fieldset class="full"><legend>${esc(tr('كميات الأصناف المستردة فعليًا','Actual refunded item quantities'))}</legend><div class="form-columns">${Object.entries(q).map(([pid,i])=>field(`${i.name} · ${tr('الحد الأصلي','Original maximum')}: ${i.quantity}`,`quantity:${pid}`,0,{type:'number',min:0,step:1})).join('')}</div></fieldset>${textarea(tr('سبب الاسترداد ومرجعه الفعلي','Refund reason and actual reference'),'reason','',true)}${check(tr('أُعيد المبلغ للعميل فعليًا','The amount was actually refunded to the customer'),'confirmed')}${formEnd(tr('اعتماد وحفظ الاسترداد','Authorize and save refund'))}</form>`,async fd=>{if(!fd.has('confirmed'))throw new Error(tr('أكد الاسترداد الفعلي للعميل.','Confirm the actual customer refund.'));const line_quantities={};for(const pid of Object.keys(q)){const n=Number(fd.get(`quantity:${pid}`));if(!Number.isInteger(n)||n<0||n>q[pid].quantity)throw new Error(tr('كمية الاسترداد غير صحيحة.','Invalid refund quantity.'));if(n)line_quantities[pid]=n;}await mutation(`/api/orders/${encodeURIComponent(id)}/refund`,{amount_halalas:cents(fd.get('amount')),method:o.payment_method,reason:fd.get('reason'),line_quantities,shift_id:fd.get('shift_id')||null});closeModal();await loadPage();}); }
  function cashEvent(id) { modal(tr('قيد عهدة مأذون — المالك','Authorized custody entry — owner'),`<form class="form-columns"><label>${esc(tr('نوع القيد','Entry type'))}<select name="kind"><option value="direct_receipt">${esc(tr('استلام مباشر مأذون','Authorized direct receipt'))}</option><option value="expense">${esc(tr('مصروف مأذون من العهدة','Authorized custody expense'))}</option><option value="adjustment">${esc(tr('تصحيح مرتبط بسجل','Linked correction'))}</option></select></label>${amountField(tr('المبلغ بالريال','Amount (SAR)'),'amount',0)}<label>${esc(tr('اتجاه التصحيح فقط','Correction direction only'))}<select name="sign"><option value="1">${esc(tr('إضافة إلى العهدة','Increase custody'))}</option><option value="-1">${esc(tr('طرح من العهدة','Decrease custody'))}</option></select></label>${field(tr('مرجع القيد المرتبط','Linked entry reference'),'reference','',{required:true})}${textarea(tr('سبب الاعتماد','Approval reason'),'reason','',true)}${check(tr('أقر القيد الفعلي وأثره في الرصيد','I approve the actual entry and its balance impact'),'confirmed')}${formEnd(tr('اعتماد وحفظ القيد','Authorize and save entry'))}</form>`,async fd=>{if(!fd.has('confirmed'))throw new Error(tr('أكد اعتماد القيد.','Confirm entry approval.'));const kind=fd.get('kind');let amount=cents(fd.get('amount'));if(kind==='expense')amount=-amount;else if(kind==='adjustment')amount*=Number(fd.get('sign'));await mutation(`/api/shifts/${encodeURIComponent(id)}/cash-event`,{kind,amount_halalas:amount,reason:fd.get('reason'),reference:fd.get('reference')});closeModal();await loadPage();}); }
  function operationalConfirmation(id){modal(tr('نتيجة الاتصال التشغيلي','Operational call outcome'),`<form><label>${esc(tr('النتيجة الفعلية','Actual outcome'))}<select name="result"><option value="reached">${esc(tr('تم التواصل وتأكيد الطلب تشغيليًا','Reached — order operationally confirmed'))}</option><option value="unreachable">${esc(tr('تعذر التواصل','Could not reach'))}</option></select></label>${textarea(tr('سياق الاتصال وسببه','Call context and reason'),'reason','',true)}${notice(tr('هذه مراجعة تشغيلية، وليست توثيقًا للجوال. لا تسجل تواصلًا لم يحدث.','This is an operational check, not phone verification. Record only a call that happened.'))}${formEnd(tr('حفظ نتيجة الاتصال','Save call result'))}</form>`,async fd=>{await mutation(`/api/orders/${encodeURIComponent(id)}/operational-confirmation`,{result:fd.get('result'),reason:fd.get('reason')});closeModal();await loadPage();});}
  function staffList(users){return `<div class="toolbar"><p class="muted">${esc(tr('نفس السائق وشفت وتقفيلة واحدة عبر الفروع المخولة. الدخول بعد إثبات البريد.','One driver, shift and closure across permitted branches. Sign-in follows email proof.'))}</p><button data-action="invite-staff">${esc(tr('إضافة سائق / دعوة موظف','Add driver / invite staff'))}</button></div>${table([tr('الاسم','Name'),tr('البريد','Email'),tr('الفروع','Branches'),tr('التفعيل / الشفت','Activation / shift'),tr('التوفر','Availability'),tr('الإجراءات','Actions')],users.map(u=>[esc(u.display_name),`<span dir="ltr">${esc(u.email||'—')}</span>`,esc((u.branch_ids||[]).map(id=>state.branches.find(b=>b.id===id)?.name||id).join(' · ')),`${esc(u.email_verified_at?tr('بريد موثق','Verified email'):({draft:tr('مسودة — البريد غير مهيأ','Draft — email unconfigured'),pending_email:tr('بانتظار إثبات البريد','Awaiting email proof'),active:tr('مفعل','Active'),paused:tr('متوقف','Paused'),revoked:tr('الدعوة ملغاة','Invitation revoked')})[u.invitation_status]||tr('بانتظار الدعوة','Invitation pending'))} · ${esc(u.active?tr('مفعل','Active'):tr('متوقف','Disabled'))}${u.open_shift?`<br>${badge(u.open_shift.status)}`:''}`,esc(u.available?tr('متاح','Available'):tr('غير متاح','Unavailable')),`<button class="quiet small" data-action="edit-staff" data-id="${esc(u.id)}">${esc(tr('تعديل النطاق','Edit scope'))}</button>${!u.email_verified_at?`<button class="quiet small" data-action="resend-invite" data-id="${esc(u.id)}">${esc(tr('إعادة الدعوة','Resend invitation'))}</button>`:''}`]))}`;}
  async function drivers(){heading(tr('السائقون','Drivers'),tr('دعوة البريد وحالة الموظف وفروعه المخولة، مع شفت وعهدة موحدين.','Email invitations, status and permitted branches with one shift and custody.'));await loadBranches();const d=await api('/api/identity/staff');state.staff=(d.users||[]).filter(u=>u.role==='driver');$('#content').innerHTML=staffList(state.staff);}
  async function inviteStaff(id){await loadBranches();if(!state.staff){const d=await api('/api/identity/staff');state.staff=d.users||[];}const u=id?state.staff.find(x=>x.id===id):{role:'driver',branch_ids:[]};if(!u)throw new Error(tr('الموظف غير متاح ضمن نطاقك.','Staff unavailable in your scope.'));modal(id?tr('تعديل بيانات الموظف ونطاقه','Edit staff and scope'):tr('دعوة موظف بالبريد','Invite staff by email'),`<form class="form-columns">${field(tr('الاسم','Name'),'display_name',u.display_name||'',{required:true})}${field(tr('البريد الإلكتروني','Email'),'email',u.email||'',{type:'email',dir:'ltr',required:true})}${field(tr('رقم الاتصال','Contact phone'),'phone',u.phone||'',{dir:'ltr',required:true})}${field(tr('رقم الموظف — اختياري','Employee reference — optional'),'employee_ref',u.employee_ref||'')}${field(tr('بيانات المركبة — اختياري','Vehicle — optional'),'vehicle',u.vehicle?.description||'')}${isAdmin()?`<label>${esc(tr('الدور','Role'))}<select name="role">${['driver','branch_manager','delivery_manager','delivery_staff',...(state.user.role==='owner'?['owner']:[])].map(role=>`<option value="${role}" ${u.role===role?'selected':''}>${esc(roleName(role))}</option>`).join('')}</select></label>`:`<input type="hidden" name="role" value="driver">`}${id?check(tr('الموظف مفعل — يظل تحقق البريد شرطًا مستقلًا','Staff enabled — email verification is separate'),'active',u.active):''}${branchChecks('scope',u.branch_ids||[])}${id?textarea(tr('سبب تعديل النطاق / التفعيل','Reason for scope / status change'),'reason','',true):''}${notice(tr('الدعوة لا تثبت وصول البريد أو تفعيل الموظف. الصلاحيات تُتحقق على الخادم، والمهام والعهدة الحالية تبقى محفوظة عند سحب نطاق.','Invitation does not prove email arrival or activation. The server validates scope; current tasks and custody remain preserved on scope withdrawal.'))}${state.user.role==='owner'?field(tr('كلمة مرور المالك الحالية — مطلوبة لدعوة مالك أو مدير','Current owner password — required for owner or manager invitation'),'step_up_password','',{type:'password',dir:'ltr'}):''}${formEnd(id?tr('حفظ نطاق الموظف','Save staff scope'):tr('حفظ الدعوة وإرسالها عبر القناة المهيأة','Save invitation through configured channel'))}</form>`,async fd=>{const body={display_name:fd.get('display_name'),phone:fd.get('phone'),branch_ids:checkedBranches(fd,'scope'),employee_ref:fd.get('employee_ref')||'',vehicle:{description:fd.get('vehicle')||''},role:isAdmin()?fd.get('role'):'driver'};if(id){body.active=fd.has('active');delete body.role;if(fd.get('email')!==u.email)body.email=fd.get('email');if(u.role==='owner'&&body.email)await mutation('/api/identity/step-up',{password:fd.get('step_up_password')||''});}else body.email=fd.get('email');if(['owner','delivery_manager'].includes(body.role)&&!id)await mutation('/api/identity/step-up',{password:fd.get('step_up_password')||''});const result=await api(id?`/api/identity/staff/${encodeURIComponent(id)}`:'/api/identity/staff/invitations',{method:id?'PATCH':'POST',body});closeModal();state.staff=null;await loadPage();setStatus(result.delivery_status==='channel_unavailable'?tr('حُفظت مسودة الموظف؛ قناة البريد بانتظار الإعداد. لم تُرسل دعوة.','Staff draft saved; email channel awaits setup. No invitation was sent.'):result.delivery_status?`${tr('حالة البريد','Email status')}: ${result.delivery_status==='queued'?tr('حُفظت الدعوة في انتظار إرسال البريد','Invitation saved, awaiting email send'):result.delivery_status}`:tr('تم حفظ الدعوة؛ راجع حالة البريد والتفعيل.','Invitation saved; review email and activation status.'));});}
  async function serviceSettings(){const cfg=state.config||await api('/api/admin/config');const services=cfg.brand?.settings?.services||{};modal(tr('خدمات البراند','Brand services'),`<form>${['delivery','pickup','car_pickup'].map(v=>check(({delivery:tr('التوصيل','Delivery'),pickup:tr('الاستلام من الفرع','Branch pickup'),car_pickup:tr('الاستلام بالسيارة','Car pickup')})[v],v,services[v]!==false)).join('')}${textarea(tr('سبب التغيير','Reason'),'reason','',true)}${notice(tr('إيقاف خدمة على مستوى البراند يمنعها للطلبات الجديدة ولا يلغي الطلبات القائمة. إتاحة الفرع والمدينة والتغطية تبقى مستقلة.','Disabling a brand service affects new orders without cancelling current orders. Branch, city and coverage eligibility remain independent.'),'warn')}${formEnd(tr('حفظ الخدمات','Save services'))}</form>`,async fd=>{await api('/api/admin/brand-services',{method:'PATCH',body:{services:Object.fromEntries(['delivery','pickup','car_pickup'].map(v=>[v,fd.has(v)])),reason:fd.get('reason')}});state.branches=[];closeModal();await loadPage();});}
  async function deliveryOnly(){await loadBranches();modal(tr('التوصيل فقط','Delivery only'),`<form>${branchChecks('scope',[])}${notice(tr('سيُوقف الاستلام العادي والسيارة في الفروع المختارة. هذا الإجراء لا يفعل التوصيل؛ قد يصبح فرع غير مؤهل متوقفًا لجميع الطلبات الجديدة. الطلبات الحالية تبقى محفوظة.','This disables pickup and car pickup in selected branches. It does not enable delivery; an ineligible branch may accept no new orders. Current orders remain preserved.'),'warn')}${textarea(tr('سبب التغيير','Reason'),'reason','',true)}${check(tr('أؤكد إيقاف الاستلام العادي والسيارة في النطاق المحدد','I confirm disabling pickup and car pickup in selected branches'),'confirm')}${formEnd(tr('اعتماد التوصيل فقط للنطاق المحدد','Apply delivery-only policy'))}</form>`,async fd=>{if(!fd.has('confirm'))throw new Error(tr('يلزم تأكيد التغيير.','Confirm the change.'));const ids=checkedBranches(fd,'scope');if(!ids.length)throw new Error(tr('حدد فرعًا واحدًا على الأقل.','Select at least one branch.'));const result=await mutation('/api/admin/delivery-only',{branch_ids:ids,confirm:true,reason:fd.get('reason')});state.branches=[];closeModal();await loadPage();if(result.warnings?.length)setStatus(result.warnings.map(x=>typeof x==='string'?x:x.message||x.reason||'').join(' · '),true);});}
